CREATE FUNCTION offline.guard_numbering_range_history() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE trusted_actor text := current_setting('app.actor_id', true);
BEGIN
  -- The whitespace set is ECMAScript String.trim(), matching Database.requireActor.
  IF btrim(trusted_actor, E' \t\n\r\f\013' ||
      U&'\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') = ''
  THEN trusted_actor := NULL; END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.created_by IS NOT NULL OR OLD.creation_key IS NOT NULL OR OLD.cancelled_by IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'STY49', MESSAGE = 'Administered numbering range history cannot be deleted.';
    END IF;
    RETURN OLD;
  END IF;
  IF current_user <> pg_get_userbyid((SELECT relowner FROM pg_catalog.pg_class
      WHERE oid = TG_RELID)) THEN
    IF (TG_OP = 'INSERT' AND NEW.created_by IS NOT NULL
        AND NEW.created_by IS DISTINCT FROM trusted_actor)
      OR (((TG_OP = 'INSERT' AND NEW.cancelled_at IS NOT NULL)
          OR (TG_OP = 'UPDATE' AND OLD.cancelled_at IS NULL AND NEW.cancelled_at IS NOT NULL))
        AND NEW.cancelled_by IS DISTINCT FROM trusted_actor)
    THEN
      RAISE EXCEPTION USING ERRCODE = 'STY48', MESSAGE = 'Range provenance must use the trusted transaction actor.';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
  IF ((OLD.created_by IS NOT NULL OR OLD.creation_key IS NOT NULL OR OLD.cancelled_by IS NOT NULL)
      AND NEW.id IS DISTINCT FROM OLD.id)
    OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.creation_key IS DISTINCT FROM OLD.creation_key
    OR NEW.creation_fingerprint IS DISTINCT FROM OLD.creation_fingerprint
    OR NEW.creation_receipt IS DISTINCT FROM OLD.creation_receipt
    OR (OLD.cancelled_at IS NOT NULL AND (
      NEW.cancelled_at IS DISTINCT FROM OLD.cancelled_at OR NEW.cancelled_by IS DISTINCT FROM OLD.cancelled_by
      OR NEW.cancellation_reason IS DISTINCT FROM OLD.cancellation_reason))
    OR (OLD.status = 'cancelled' AND NEW.status <> 'cancelled')
    OR (OLD.created_by IS NOT NULL AND NEW.consumer_attributes::text IS DISTINCT FROM OLD.consumer_attributes::text)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'STY48', MESSAGE = 'Numbering range provenance and terminal history are immutable.';
  END IF;
  IF (NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.org_unit_id IS DISTINCT FROM OLD.org_unit_id
    OR NEW.entity_type IS DISTINCT FROM OLD.entity_type OR NEW.series IS DISTINCT FROM OLD.series
    OR NEW.start_number IS DISTINCT FROM OLD.start_number OR NEW.end_number IS DISTINCT FROM OLD.end_number)
    AND EXISTS (SELECT 1 FROM offline.numbering_reservations r WHERE r.tenant_id = OLD.tenant_id AND r.range_id = OLD.id)
  THEN
    RAISE EXCEPTION USING ERRCODE = 'STY48', MESSAGE = 'Referenced numbering range bounds and scope are immutable.';
  END IF;
  RETURN NEW;
END
$guard$;

CREATE TRIGGER numbering_ranges_history_guard BEFORE INSERT OR UPDATE OR DELETE ON offline.numbering_ranges
  FOR EACH ROW EXECUTE FUNCTION offline.guard_numbering_range_history();

CREATE TABLE offline.sync_import_receipts (
  source_identity_sha256 text PRIMARY KEY
    CHECK (source_identity_sha256 ~ '^sha256:[0-9a-f]{64}$'),
  source_system text NOT NULL CHECK (octet_length(source_system) BETWEEN 1 AND 255),
  source_snapshot_id text NOT NULL CHECK (octet_length(source_snapshot_id) BETWEEN 1 AND 4096),
  source_sha256 text NOT NULL CHECK (source_sha256 ~ '^sha256:[0-9a-f]{64}$'),
  manifest_sha256 text NOT NULL CHECK (manifest_sha256 ~ '^sha256:[0-9a-f]{64}$'),
  mapping_sha256 text NOT NULL CHECK (mapping_sha256 ~ '^sha256:[0-9a-f]{64}$'),
  original_manifest jsonb NOT NULL CHECK (jsonb_typeof(original_manifest) = 'object'),
  imported_by text NOT NULL CHECK (octet_length(imported_by) BETWEEN 1 AND 63),
  imported_at timestamptz NOT NULL CHECK (isfinite(imported_at)),
  receipt jsonb NOT NULL CHECK (jsonb_typeof(receipt) = 'object')
);

ALTER TABLE offline.sync_import_receipts ENABLE ROW LEVEL SECURITY;

ALTER TABLE offline.sync_import_receipts FORCE ROW LEVEL SECURITY;

CREATE FUNCTION offline.guard_sync_import_receipt() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
BEGIN
  RAISE EXCEPTION USING ERRCODE = 'STY50', MESSAGE = 'Offline import receipts are append-only.';
END
$guard$;

CREATE TRIGGER sync_import_receipts_append_only BEFORE UPDATE OR DELETE ON offline.sync_import_receipts
  FOR EACH ROW EXECUTE FUNCTION offline.guard_sync_import_receipt();

ALTER TABLE offline.sync_batches ADD COLUMN response_body_is_archived boolean NOT NULL DEFAULT false;

CREATE FUNCTION offline.guard_archived_sync_batch() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE table_owner name;
BEGIN
  IF TG_OP <> 'INSERT' AND OLD.response_body_is_archived THEN
    IF TG_OP = 'DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION USING ERRCODE = 'STY51', MESSAGE = 'Verified archived batch responses are immutable.';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW.response_body_is_archived THEN
    SELECT pg_get_userbyid(c.relowner) INTO table_owner FROM pg_class c WHERE c.oid=TG_RELID;
    IF current_user <> table_owner THEN
      RAISE EXCEPTION USING ERRCODE = 'STY52', MESSAGE = 'Archived response admission requires the actual table owner.';
    END IF;
    IF NEW.status <> 'closed' OR NEW.response_status IS DISTINCT FROM 201
       OR NEW.response_body_bytes IS NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'STY53', MESSAGE = 'Verified archived response lifecycle is invalid.';
    END IF;
  END IF;
  RETURN NEW;
END
$guard$;

CREATE TRIGGER sync_batches_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON offline.sync_batches
  FOR EACH ROW EXECUTE FUNCTION offline.guard_archived_sync_batch();

CREATE TABLE offline.numbering_reconciliations (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES "auth"."tenants"("id") ON DELETE RESTRICT,
  reservation_id uuid NOT NULL,
  actor_id text NOT NULL CHECK (octet_length(actor_id) BETWEEN 1 AND 255),
  created_at timestamptz NOT NULL CHECK (isfinite(created_at)),
  claimed_numbers bigint[] NOT NULL CHECK (array_position(claimed_numbers, NULL) IS NULL),
  user_ref text CHECK (user_ref IS NULL OR octet_length(user_ref) <= 255),
  idempotency_key text CHECK (idempotency_key IS NULL OR octet_length(idempotency_key) BETWEEN 1 AND 255),
  request_fingerprint text CHECK (request_fingerprint IS NULL OR request_fingerprint ~ '^sha256:[0-9a-f]{64}$'),
  result_json jsonb NOT NULL CHECK (jsonb_typeof(result_json) = 'object'),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id, reservation_id) REFERENCES offline.numbering_reservations (tenant_id, id) ON DELETE RESTRICT,
  CHECK ((idempotency_key IS NULL AND request_fingerprint IS NULL)
    OR (idempotency_key IS NOT NULL AND request_fingerprint IS NOT NULL))
);

CREATE UNIQUE INDEX numbering_reconciliations_replay_uq
  ON offline.numbering_reconciliations (tenant_id, reservation_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

CREATE INDEX numbering_reconciliations_reservation_history_idx
  ON offline.numbering_reconciliations (tenant_id, reservation_id, created_at DESC, id DESC);

ALTER TABLE offline.numbering_reconciliations ENABLE ROW LEVEL SECURITY;

ALTER TABLE offline.numbering_reconciliations FORCE ROW LEVEL SECURITY;

CREATE FUNCTION offline.guard_numbering_reconciliation_history() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE trusted_actor text := current_setting('app.actor_id', true);
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE = 'STY54', MESSAGE = 'Numbering reconciliation history is append-only.';
  END IF;
  IF current_user <> pg_get_userbyid((SELECT relowner FROM pg_catalog.pg_class WHERE oid = TG_RELID))
    AND NEW.actor_id IS DISTINCT FROM trusted_actor THEN
    RAISE EXCEPTION USING ERRCODE = 'STY55', MESSAGE = 'Reconciliation provenance must use the trusted transaction actor.';
  END IF;
  RETURN NEW;
END
$guard$;

CREATE TRIGGER numbering_reconciliations_history_guard BEFORE INSERT OR UPDATE OR DELETE
  ON offline.numbering_reconciliations FOR EACH ROW EXECUTE FUNCTION offline.guard_numbering_reconciliation_history();

